fn solve(input: Vec<char>) -> Vec<char> {
    // The input format must be:
    // "AtCoder {Name} Contest\n"
    // where:
    // - "AtCoder " is fixed prefix (8 chars)
    // - {Name} is a non-empty word starting uppercase then lowercase letters
    // - followed by space
    // - followed by "Contest"
    // - followed by newline '\n'
    //
    // We must extract the first character of {Name} (the uppercase initial),
    // then output "A{Initial}C\n" as a Vec<char>.

    // Check prefix "AtCoder "
    let prefix = ['A', 't', 'C', 'o', 'd', 'e', 'r', ' '];
    for i in 0..prefix.len() {
        if input[i] != prefix[i] {
            // The problem states we can assume the format; no need for error handling.
            // Just return empty or unreachable, but here we just continue.
            return vec![];
        }
    }

    // The name starts at index 8 (the char after "AtCoder ")
    // Extract the name until the next space
    let mut name_start = 8;
    let mut name_end = name_start;

    while name_end < input.len() && input[name_end] != ' ' {
        name_end += 1;
    }

    // name must be non-empty: name_end > name_start
    if name_end == name_start {
        return vec![];
    }

    // Validate the name: first char uppercase A-Z,
    // rest lowercase a-z
    let first_char = input[name_start];
    if !(first_char >= 'A' && first_char <= 'Z') {
        return vec![];
    }

    for &ch in &input[name_start + 1..name_end] {
        if !(ch >= 'a' && ch <= 'z') {
            return vec![];
        }
    }

    // After the name and space, must have "Contest\n" exactly
    // So input[name_end] == ' ' is next separator
    // Check next characters after input[name_end] == ' '
    let contest_str = ['C', 'o', 'n', 't', 'e', 's', 't', '\n'];
    if name_end >= input.len() - contest_str.len() {
        return vec![];
    }

    if input[name_end] != ' ' {
        return vec![];
    }

    for i in 0..contest_str.len() {
        if input[name_end + 1 + i] != contest_str[i] {
            return vec![];
        }
    }

    // Build and return the result "A{NameInitial}C\n"
    build_result(first_char)
}

fn build_result(ch: char) -> Vec<char> {
    vec!['A', ch, 'C', '\n']
}